package io.robrichardson.inventorycount;

import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import net.runelite.api.Client;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.FontType;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

/**
 * Covers InventoryCountOverlay's per-mode text selection and position mapping added
 * for InventoryCountMode (card #1): FREE/USED render their single text at the configured
 * position; BOTH renders free at the configured position and used at the opposite end,
 * with Center resolving to free-Top/used-Bottom.
 *
 * The widget bounds and font metrics are fixed constants below so each expected pixel
 * position can be derived by hand rather than re-deriving overlay internals in the test.
 */
@RunWith(MockitoJUnitRunner.class)
public class InventoryCountOverlayModeTest
{
	private static final Rectangle WIDGET_BOUNDS = new Rectangle(0, 0, 100, 100);
	private static final int FONT_HEIGHT = 20;
	private static final int MAX_DESCENT = 5;
	private static final int TEXT_HEIGHT = FONT_HEIGHT - MAX_DESCENT; // 15
	private static final int STRING_WIDTH = 10;

	// Matches getInventoryOverlayText's layout math for the constants above.
	private static final int EXPECTED_X = (int) WIDGET_BOUNDS.getCenterX() - (STRING_WIDTH / 2); // 45
	private static final int TOP_Y = (int) WIDGET_BOUNDS.getMinY() + TEXT_HEIGHT; // 15
	private static final int BOTTOM_Y = (int) WIDGET_BOUNDS.getMaxY(); // 100

	@Mock
	private Client client;

	@Mock
	private InventoryCountPlugin plugin;

	@Mock
	private InventoryCountConfig config;

	@Mock
	private ConfigManager configManager;

	@Mock
	private Widget inventoryWidget;

	@Mock
	private Graphics2D graphics;

	@Mock
	private FontMetrics fontMetrics;

	private InventoryCountOverlay overlay;

	@Before
	public void setUp()
	{
		when(configManager.getConfiguration("runelite", "infoboxFontType", FontType.class)).thenReturn(FontType.REGULAR);

		overlay = new InventoryCountOverlay(client, plugin, config, configManager);

		when(config.renderInventoryOverlay()).thenReturn(true);
		when(client.getWidget(ComponentID.FIXED_VIEWPORT_INVENTORY_TAB)).thenReturn(inventoryWidget);
		when(inventoryWidget.isHidden()).thenReturn(false);
		when(inventoryWidget.getBounds()).thenReturn(WIDGET_BOUNDS);

		when(graphics.getFontMetrics()).thenReturn(fontMetrics);
		when(fontMetrics.getHeight()).thenReturn(FONT_HEIGHT);
		when(fontMetrics.getMaxDescent()).thenReturn(MAX_DESCENT);
		when(fontMetrics.stringWidth(org.mockito.ArgumentMatchers.anyString())).thenReturn(STRING_WIDTH);

		overlay.setFreeText("23");
		overlay.setUsedText("5");
	}

	private void verifyTextDrawnAt(String text, int y)
	{
		verify(graphics).drawString(eq(text), eq(EXPECTED_X), eq(y));
	}

	private void verifyTextNeverDrawn(String text)
	{
		verify(graphics, never()).drawString(eq(text), org.mockito.ArgumentMatchers.anyInt(), org.mockito.ArgumentMatchers.anyInt());
	}

	@Test
	public void freeModeRendersOnlyFreeTextAtConfiguredPosition()
	{
		overlay.setMode(InventoryCountMode.FREE);
		when(config.inventoryOverlayTextPosition()).thenReturn(InventoryOverlayTextPositions.Bottom);

		overlay.render(graphics);

		verifyTextDrawnAt("23", BOTTOM_Y);
		verifyTextNeverDrawn("5");
	}

	@Test
	public void usedModeRendersOnlyUsedTextAtConfiguredPosition()
	{
		overlay.setMode(InventoryCountMode.USED);
		when(config.inventoryOverlayTextPosition()).thenReturn(InventoryOverlayTextPositions.Top);

		overlay.render(graphics);

		verifyTextDrawnAt("5", TOP_Y);
		verifyTextNeverDrawn("23");
	}

	@Test
	public void bothModeAtBottomRendersFreeAtBottomAndUsedAtTop()
	{
		overlay.setMode(InventoryCountMode.BOTH);
		when(config.inventoryOverlayTextPosition()).thenReturn(InventoryOverlayTextPositions.Bottom);

		overlay.render(graphics);

		verifyTextDrawnAt("23", BOTTOM_Y);
		verifyTextDrawnAt("5", TOP_Y);
	}

	@Test
	public void bothModeAtTopRendersFreeAtTopAndUsedAtBottom()
	{
		overlay.setMode(InventoryCountMode.BOTH);
		when(config.inventoryOverlayTextPosition()).thenReturn(InventoryOverlayTextPositions.Top);

		overlay.render(graphics);

		verifyTextDrawnAt("23", TOP_Y);
		verifyTextDrawnAt("5", BOTTOM_Y);
	}

	@Test
	public void bothModeAtCenterRendersFreeAtTopAndUsedAtBottom()
	{
		overlay.setMode(InventoryCountMode.BOTH);
		when(config.inventoryOverlayTextPosition()).thenReturn(InventoryOverlayTextPositions.Center);

		overlay.render(graphics);

		verifyTextDrawnAt("23", TOP_Y);
		verifyTextDrawnAt("5", BOTTOM_Y);
	}
}

package io.robrichardson.inventorycount;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

import java.awt.Color;
import net.runelite.client.plugins.Plugin;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

/**
 * Covers InventoryCountInfoBox's per-mode text/tooltip and the free-slots-based text color,
 * added alongside InventoryCountMode (card #1).
 */
@RunWith(MockitoJUnitRunner.class)
public class InventoryCountInfoBoxModeTest
{
	@Mock
	private InventoryCountConfig config;

	@Mock
	private Plugin plugin;

	private InventoryCountInfoBox infoBox;

	@Before
	public void setUp()
	{
		when(config.renderInventoryInfoBox()).thenReturn(true);
		infoBox = new InventoryCountInfoBox(null, plugin, config);
	}

	@Test
	public void freeModeShowsFreeCount()
	{
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.FREE);
		infoBox.setCounts(23, 5);

		assertEquals("23", infoBox.getText());
	}

	@Test
	public void usedModeShowsUsedCount()
	{
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.USED);
		infoBox.setCounts(23, 5);

		assertEquals("5", infoBox.getText());
	}

	@Test
	public void bothModeShowsFreeCount()
	{
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.BOTH);
		infoBox.setCounts(23, 5);

		assertEquals("23", infoBox.getText());
	}

	@Test
	public void freeModeTooltip()
	{
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.FREE);
		infoBox.setCounts(23, 5);

		assertEquals("23 free inventory slots", infoBox.getTooltip());
	}

	@Test
	public void usedModeTooltip()
	{
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.USED);
		infoBox.setCounts(23, 5);

		assertEquals("5 used inventory slots", infoBox.getTooltip());
	}

	@Test
	public void bothModeTooltipJoinsFreeAndUsed()
	{
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.BOTH);
		infoBox.setCounts(23, 5);

		assertEquals("23 free inventory slots</br>5 used inventory slots", infoBox.getTooltip());
	}

	@Test
	public void freeModeTooltipIsSingularWhenOneFreeSlot()
	{
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.FREE);
		infoBox.setCounts(1, 27);

		assertEquals("1 free inventory slot", infoBox.getTooltip());
	}

	@Test
	public void usedModeTooltipIsSingularWhenOneUsedSlot()
	{
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.USED);
		infoBox.setCounts(27, 1);

		assertEquals("1 used inventory slot", infoBox.getTooltip());
	}

	@Test
	public void textColorIsRedWhenNoFreeSlots()
	{
		infoBox.setCounts(0, 28);

		assertEquals(Color.RED, infoBox.getTextColor());
	}

	@Test
	public void textColorIsWhiteWhenAnyFreeSlots()
	{
		infoBox.setCounts(1, 27);

		assertEquals(Color.WHITE, infoBox.getTextColor());
	}

	@Test
	public void textColorIsWhiteWhenAllSlotsFree()
	{
		infoBox.setCounts(28, 0);

		assertEquals(Color.WHITE, infoBox.getTextColor());
	}
}

package io.robrichardson.inventorycount;

import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

/**
 * Covers the free/used slot computation and dynamic-colour behaviour added for
 * InventoryCountMode (card #1): updateOverlays() should push both free and used counts
 * to the overlay and infobox, and dynamic colour should keep deriving from free slots
 * regardless of which mode is configured.
 */
@RunWith(MockitoJUnitRunner.class)
public class InventoryCountPluginCountModeTest
{
	@Mock
	private Client client;

	@Mock
	private ClientThread clientThread;

	@Mock
	private InfoBoxManager infoBoxManager;

	@Mock
	private InventoryCountOverlay overlay;

	@Mock
	private OverlayManager overlayManager;

	@Mock
	private InventoryCountConfig config;

	@Mock
	private ItemContainer itemContainer;

	@InjectMocks
	private InventoryCountPlugin plugin;

	private final List<Runnable> clientThreadQueue = new ArrayList<>();

	@Before
	public void setUp() throws Exception
	{
		doAnswer(inv ->
		{
			clientThreadQueue.add(inv.getArgument(0));
			return null;
		}).when(clientThread).invoke(any(Runnable.class));

		when(config.renderInventoryOverlay()).thenReturn(true);
		when(config.renderInventoryInfoBox()).thenReturn(true);
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.FREE);

		when(client.getItemContainer(net.runelite.api.InventoryID.INVENTORY)).thenReturn(itemContainer);
	}

	private void drainClientThread()
	{
		List<Runnable> pending = new ArrayList<>(clientThreadQueue);
		clientThreadQueue.clear();
		pending.forEach(Runnable::run);
	}

	/** 28-slot inventory with {@code usedCount} real items (id != -1) and the rest empty (-1). */
	private static Item[] inventoryWith(int usedCount)
	{
		Item[] items = new Item[28];
		for (int i = 0; i < 28; i++)
		{
			items[i] = new Item(i < usedCount ? 1 : -1, 1);
		}
		return items;
	}

	/**
	 * startUp() queues toggleOverlayAndInfoBox() -> updateOverlays() onto the client thread,
	 * so draining the queue is enough to trigger a computation; onItemContainerChanged is
	 * private and not reachable from the test, but it calls the same updateOverlays() method.
	 */
	private void triggerUpdate(int usedCount) throws Exception
	{
		when(itemContainer.getItems()).thenReturn(inventoryWith(usedCount));

		plugin.startUp();
		drainClientThread();
	}

	@Test
	public void updateOverlaysPushesFreeAndUsedCountsToOverlay() throws Exception
	{
		triggerUpdate(5);

		verify(overlay).setFreeText("23");
		verify(overlay).setUsedText("5");
	}

	@Test
	public void updateOverlaysPushesFreeAndUsedCountsToInfoBox() throws Exception
	{
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.BOTH);
		triggerUpdate(5);

		InventoryCountInfoBox infoBox = plugin.getInventoryCountInfoBox();
		assertEquals("23 free inventory slots</br>5 used inventory slots", infoBox.getTooltip());
	}

	@Test
	public void dynamicColorInFreeModeIsRedWhenNoFreeSlots() throws Exception
	{
		when(config.dynamicInventoryOverlayColor()).thenReturn(true);
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.FREE);

		triggerUpdate(28); // 0 free slots

		verify(overlay).setColor(Color.RED);
	}

	@Test
	public void dynamicColorInUsedModeStillDerivesFromFreeSlots() throws Exception
	{
		when(config.dynamicInventoryOverlayColor()).thenReturn(true);
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.USED);

		triggerUpdate(28); // 0 free, 28 used -> red despite USED mode
		verify(overlay).setColor(Color.RED);
	}

	@Test
	public void dynamicColorInUsedModeIsGreenWhenAllSlotsFree() throws Exception
	{
		when(config.dynamicInventoryOverlayColor()).thenReturn(true);
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.USED);

		triggerUpdate(0); // 28 free, 0 used -> green
		verify(overlay).setColor(Color.GREEN);
	}

	@Test
	public void dynamicColorInBothModeIsRedWhenNoFreeSlots() throws Exception
	{
		when(config.dynamicInventoryOverlayColor()).thenReturn(true);
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.BOTH);

		triggerUpdate(28);
		verify(overlay).setColor(Color.RED);
	}

	@Test
	public void dynamicColorInBothModeIsGreenWhenAllSlotsFree() throws Exception
	{
		when(config.dynamicInventoryOverlayColor()).thenReturn(true);
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.BOTH);

		triggerUpdate(0);
		verify(overlay).setColor(Color.GREEN);
	}

	@Test
	public void modeIsPushedToOverlay() throws Exception
	{
		when(config.inventoryCountMode()).thenReturn(InventoryCountMode.BOTH);
		triggerUpdate(10);

		verify(overlay).setMode(InventoryCountMode.BOTH);
	}
}

