package io.robrichardson.inventorycount;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.when;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

/**
 * Reproduces https://github.com/robrichardson13/inventory-count/issues/13.
 *
 * RuneLite starts and stops plugins on the Swing EDT, but the plugin queues its
 * "add overlay" work onto the client thread. If the plugin is disabled before that
 * queued work drains, the overlay is added after shutDown() and nothing ever removes it.
 */
@RunWith(MockitoJUnitRunner.class)
public class InventoryCountPluginShutDownTest
{
	@Mock
	private Client client;

	@Mock
	private ClientThread clientThread;

	@Mock
	private InfoBoxManager infoBoxManager;

	@Mock
	private InventoryCountOverlay overlay;

	@Mock
	private OverlayManager overlayManager;

	@Mock
	private InventoryCountConfig config;

	@InjectMocks
	private InventoryCountPlugin plugin;

	/** Tasks queued to the fake client thread, drained manually by the test. */
	private final List<Runnable> clientThreadQueue = new ArrayList<>();

	/** Fake OverlayManager / InfoBoxManager state so we can assert what is actually on screen. */
	private final Set<Overlay> visibleOverlays = new HashSet<>();
	private final Set<InfoBox> visibleInfoBoxes = new HashSet<>();

	@Before
	public void setUp()
	{
		doAnswer(inv ->
		{
			clientThreadQueue.add(inv.getArgument(0));
			return null;
		}).when(clientThread).invoke(any(Runnable.class));

		doAnswer(inv -> visibleOverlays.add(inv.getArgument(0))).when(overlayManager).add(any(Overlay.class));
		doAnswer(inv -> visibleOverlays.remove(inv.getArgument(0))).when(overlayManager).remove(any(Overlay.class));

		doAnswer(inv ->
		{
			visibleInfoBoxes.add(inv.getArgument(0));
			return null;
		}).when(infoBoxManager).addInfoBox(any(InfoBox.class));
		doAnswer(inv ->
		{
			visibleInfoBoxes.remove(inv.getArgument(0));
			return null;
		}).when(infoBoxManager).removeInfoBox(any(InfoBox.class));

		when(config.renderInventoryOverlay()).thenReturn(true);
		when(config.renderInventoryInfoBox()).thenReturn(true);
	}

	private void drainClientThread()
	{
		List<Runnable> pending = new ArrayList<>(clientThreadQueue);
		clientThreadQueue.clear();
		pending.forEach(Runnable::run);
	}

	@Test
	public void startUpShowsOverlayAndInfoBoxOnceClientThreadRuns() throws Exception
	{
		plugin.startUp();
		drainClientThread();

		assertTrue("overlay should be shown after startUp", visibleOverlays.contains(overlay));
		assertFalse("infobox should be shown after startUp", visibleInfoBoxes.isEmpty());
	}

	@Test
	public void disablingPluginBeforeClientThreadRunsLeavesNothingOnScreen() throws Exception
	{
		plugin.startUp();
		// Plugin gets disabled before the client thread has processed the queued add.
		plugin.shutDown();
		drainClientThread();

		assertFalse("overlay must not persist after plugin is disabled", visibleOverlays.contains(overlay));
		assertTrue("infobox must not persist after plugin is disabled", visibleInfoBoxes.isEmpty());
	}

	@Test
	public void disablingPluginRightAfterTogglingCounterOnLeavesNothingOnScreen() throws Exception
	{
		// Issue #13 steps: plugin enabled, "Toggle Inventory Counter" turned on, plugin disabled.
		plugin.startUp();
		drainClientThread();

		net.runelite.client.events.ConfigChanged event = new net.runelite.client.events.ConfigChanged();
		event.setGroup(InventoryCountConfig.GROUP);
		event.setKey("renderInventoryOverlay");
		event.setNewValue("true");
		plugin.onConfigChanged(event);

		plugin.shutDown();
		drainClientThread();

		assertFalse("overlay must not persist after plugin is disabled", visibleOverlays.contains(overlay));
		assertTrue("infobox must not persist after plugin is disabled", visibleInfoBoxes.isEmpty());
	}
}

package io.robrichardson.inventorycount;

import javax.inject.Inject;

import com.google.inject.Provides;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.ImageUtil;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.Arrays;

@Slf4j
@PluginDescriptor(
        name = "Inventory Count"
)
public class InventoryCountPlugin extends Plugin {
    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private InfoBoxManager infoBoxManager;

    @Inject
    private InventoryCountOverlay overlay;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private InventoryCountConfig config;

    private static final BufferedImage INVENTORY_IMAGE;

    private static final int INVENTORY_SIZE = 28;

    @Getter
    private InventoryCountInfoBox inventoryCountInfoBox;

    /**
     * Whether the plugin is currently running. startUp/shutDown run on the Swing EDT while the
     * add/remove work is queued onto the client thread, so a queued add can execute after
     * shutDown() has already run. The queued task checks this flag and bails out in that case,
     * otherwise the overlay/infobox would be re-added with no plugin left to remove them.
     */
    private volatile boolean running;

    static {
        INVENTORY_IMAGE = ImageUtil.loadImageResource(InventoryCountPlugin.class, "inventory_icon.png");
    }

    @Override
    protected void startUp() throws Exception {
        running = true;
        toggleOverlayAndInfoBox();
    }

    @Override
    protected void shutDown() throws Exception {
        running = false;
        overlayManager.remove(overlay);
        removeInfoBox();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!InventoryCountConfig.GROUP.equals(event.getGroup())) return;

        toggleOverlayAndInfoBox();
    }

    @Provides
    InventoryCountConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(InventoryCountConfig.class);
    }

    private void toggleOverlayAndInfoBox() {
        clientThread.invoke(() -> {
            if (!running) {
                // Plugin was disabled before this task ran; don't re-add anything.
                return;
            }

            if (config.renderInventoryOverlay()) {
                overlayManager.add(overlay);
            } else {
                overlayManager.remove(overlay);
            }

            if (config.renderInventoryInfoBox()) {
                addInfoBox();
            } else {
                removeInfoBox();
            }

            updateOverlays();
        });
    }

    private void addInfoBox() {
        if (inventoryCountInfoBox == null) {
            inventoryCountInfoBox = new InventoryCountInfoBox(INVENTORY_IMAGE, this, config); // Pass config
            infoBoxManager.addInfoBox(inventoryCountInfoBox);
        }
    }

    private void removeInfoBox() {
        if (inventoryCountInfoBox != null) {
            infoBoxManager.removeInfoBox(inventoryCountInfoBox);
            inventoryCountInfoBox = null;
        }
    }

    private void updateOverlays() {
        int usedSlots = usedInventorySlots();
        int freeSlots = INVENTORY_SIZE - usedSlots;
        Color textColor = getInventoryTextColor(freeSlots);

        overlay.setMode(config.inventoryCountMode());
        overlay.setFreeText(String.valueOf(freeSlots));
        overlay.setUsedText(String.valueOf(usedSlots));
        overlay.setColor(textColor);

        if (inventoryCountInfoBox != null) {
            inventoryCountInfoBox.setCounts(freeSlots, usedSlots);
        }
    }

    public int openInventorySpaces() {
        return INVENTORY_SIZE - usedInventorySlots();
    }

    public int usedInventorySlots() {
        ItemContainer container = client.getItemContainer(InventoryID.INVENTORY);
        Item[] items = container == null ? new Item[0] : container.getItems();
        return (int) Arrays.stream(items).filter(p -> p.getId() != -1).count();
    }

    public Color getInventoryTextColor() {
        return getInventoryTextColor(openInventorySpaces());
    }

    private Color getInventoryTextColor(int freeSlots) {
        if (config.dynamicInventoryOverlayColor()) {
            if (freeSlots > InventoryOverlaySlotSizes.HIGH) {
                return Color.GREEN;
            } else if (freeSlots > InventoryOverlaySlotSizes.MEDIUM) {
                return Color.YELLOW;
            } else if (freeSlots > InventoryOverlaySlotSizes.LOW) {
                return new Color(255, 165, 0); // Light orange
            } else {
                return Color.RED;
            }
        }
        return config.customInventoryOverlayTextColor();
    }

    @Subscribe
    private void onItemContainerChanged(ItemContainerChanged event) {
        if (event.getContainerId() == InventoryID.INVENTORY.getId()) {
            updateOverlays();
        }
    }
}

package io.robrichardson.inventorycount;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

import java.awt.*;

@ConfigGroup(InventoryCountConfig.GROUP)
public interface InventoryCountConfig extends Config {
    String GROUP = "InventoryCount";

    @ConfigItem(
            keyName = "renderInventoryOverlay",
            name = "Toggle inventory counter",
            description = "Toggle for rendering the inventory count overlay",
            position = 1
    )
    default boolean renderInventoryOverlay() {
        return true;
    }

    @ConfigItem(
            keyName = "renderInventoryInfoBox",
            name = "Toggle inventory box",
            description = "Toggle for rendering the inventory info box",
            position = 2
    )
    default boolean renderInventoryInfoBox() {
        return false;
    }

    @ConfigSection(
            name = "Text Settings",
            description = "Change your text color, outline and positioning",
            position = 3
    )
